import{_ as t,c as e,o as l,ak as n}from"./chunks/framework.gmyagHYt.js";const g=JSON.parse('{"title":"主界面介绍","description":"对主界面中各部分内容进行介绍","frontmatter":{"title":"主界面介绍","description":"对主界面中各部分内容进行介绍","layout":"doc"},"headers":[],"relativePath":"version/v3/docs/base/ui-Introduction/main-Interface.md","filePath":"version/v3/docs/base/ui-Introduction/main-Interface.md","contributors":[{"name":"晚安","username":"nulijiazaizhong","avatar":"https://github.com/nulijiazaizhong.png?size=64","commits":1,"profileUrl":"https://github.com/nulijiazaizhong"}]}'),r={name:"version/v3/docs/base/ui-Introduction/main-Interface.md"};function s(c,a,o,i,p,h){return l(),e("div",null,[...a[0]||(a[0]=[n('<p><img src="https://tuchuang.ets2la.cn/csharp/20261018063556025.png" alt="" loading="lazy"> 从上面的图片中可以看到主界面ui分为了两个部分——侧边栏和功能区；侧边栏中有很多的模块，接下来以此介绍各个模块的作用是什么。</p><h2 id="仪表盘" tabindex="-1">仪表盘 <a class="header-anchor" href="#仪表盘" aria-label="Permalink to “仪表盘”">​</a></h2><p>仪表盘目前显示的是项目在GitHub上的赞助信息，包含了赞助链接和赞助用户名单的公示</p><h2 id="可视化" tabindex="-1">可视化 <a class="header-anchor" href="#可视化" aria-label="Permalink to “可视化”">​</a></h2><p>顾名思义就是用于显示插件/软件运行状态的显示，在未启用 <code>Visuakization Sockets</code> 插件的情况下显示的图一所示， <img src="https://tc.ets2la.cn/csharp/20260927091835592.png" alt="图一" loading="lazy"> 在启用了插件的情况下如图二所示 <img src="https://tc.ets2la.cn/csharp/20260927092125912.png" alt="图二" loading="lazy"></p><h2 id="插件管理" tabindex="-1">插件管理 <a class="header-anchor" href="#插件管理" aria-label="Permalink to “插件管理”">​</a></h2><p>插件管理页面中会显示所有<strong>已安装</strong>的插件，可以单独启用，也可以使用一键命令全部启用<br> 点击红色方框会在资源管理器中打开插件文件夹，点击黄色方框会重新刷新所有已安装的插件 <img src="https://tuchuang.ets2la.cn/csharp/20261018063740269.png" alt="" loading="lazy"></p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>软件更新会删除本地插件文件夹中的所有文件，需要在插件库中重新安装</p></div><h2 id="插件库" tabindex="-1">插件库 <a class="header-anchor" href="#插件库" aria-label="Permalink to “插件库”">​</a></h2><p>插件库是安装插件的地方，你可以在这里看见很多插件，这里有ETS2LA开发组编写的插件，也有许多第三方开发者编写的插件，请注意区分；找到对应的插件点击安装即可，插件安装完成之后会要求重启软件，按照要求重启即可。 <img src="https://tc.ets2la.cn/csharp/20260927092742275.png" alt="" loading="lazy"></p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>如果你的插件库是空的，请确保你是从官方地址下载的软件安装包，因为这关系到软件在后端使用什么插件源；<br> 安装包与插件源对应关系：<br> GitHub/sourceforge ——&gt; 官方地址（使用 cloudflare 进行分发）<br> CNB/国内镜像站 ——&gt; 国内镜像地址（使用华为云CDN进行分发）</p></div><h2 id="维基-常见问题" tabindex="-1">维基/常见问题 <a class="header-anchor" href="#维基-常见问题" aria-label="Permalink to “维基/常见问题”">​</a></h2><p>该页面显示的是 <a href="https://ets2la.com/help/faq/" target="_blank" rel="noreferrer">https://ets2la.com/help/faq/</a> 该网页链接的内容</p><h2 id="联系我们" tabindex="-1">联系我们 <a class="header-anchor" href="#联系我们" aria-label="Permalink to “联系我们”">​</a></h2><p>如果软件在使用过程中遇到恶行bug，可通过该页面中的地址联系开发者 <img src="https://tc.ets2la.cn/csharp/20260927094729873.png" alt="" loading="lazy"></p><h2 id="聊天机器人" tabindex="-1">聊天机器人 <a class="header-anchor" href="#聊天机器人" aria-label="Permalink to “聊天机器人”">​</a></h2><p>如果您没有登录，那么您看到的页面应该是这样的 <img src="https://tuchuang.ets2la.cn/csharp/20261018063954926.png" alt="" loading="lazy"> 在登录了账号的情况下，你看到的界面应该是这样的 <img src="https://tuchuang.ets2la.cn/csharp/20261018065858948.png" alt="" loading="lazy"></p><h2 id="设置" tabindex="-1">设置 <a class="header-anchor" href="#设置" aria-label="Permalink to “设置”">​</a></h2><p>软件的设置都在该页面中，包括但不限于数据精度的选择；该页面中的修改项大部分都有对应的描述，所以这里不多讲。 <img src="https://tuchuang.ets2la.cn/csharp/20261018063823927.png" alt="" loading="lazy"></p><h2 id="anonymous" tabindex="-1">Anonymous <a class="header-anchor" href="#anonymous" aria-label="Permalink to “Anonymous”">​</a></h2><p>这是用户系统的快捷入口，未登录状态下看到的页面应该是这样的 <img src="https://tuchuang.ets2la.cn/csharp/20261018063905547.png" alt="" loading="lazy"></p><h3 id="注册" tabindex="-1">注册 <a class="header-anchor" href="#注册" aria-label="Permalink to “注册”">​</a></h3><p>在 <code>Anonymous</code> 页面点击右侧中的 <code>没有账户? 现在就注册一个新账户，无需邮箱！</code> 按钮 <img src="https://tuchuang.ets2la.cn/csharp/20261018064205306.png" alt="" loading="lazy"> 在 <code>Username</code> 中填写上你想使用的用户名，然后点击注册 <img src="https://tuchuang.ets2la.cn/csharp/20261018064255000.png" alt="" loading="lazy"> 之后会弹出一个二维码让你进行扫码，这时候使用手机上的2FA软件进行扫码即可，然后点击 <code>返回登录界面</code> 按钮 <img src="https://tuchuang.ets2la.cn/csharp/20261018064504019.png" alt="" loading="lazy"></p><h3 id="登录" tabindex="-1">登录 <a class="header-anchor" href="#登录" aria-label="Permalink to “登录”">​</a></h3><p>上一步已经完成了注册，接下来就是登录了，上面已经点击了 <code>返回登录界面</code> 按钮，大多数情况下现在你的 <code>Username</code> 输入框中应该已经显示用户名了，如果没显示就在输入一遍用户名 <img src="https://tuchuang.ets2la.cn/csharp/20261018065303767.png" alt="" loading="lazy"> 然后在手机上打开你的2FA软件并且输入6位数的验证密码，最后点击登录即可 <img src="https://tuchuang.ets2la.cn/csharp/20261018065541873.png" alt="" loading="lazy"> 最后在登录的情况下你看到的页面应该是这样的，并且主界面的左下角应该也变成了你的用户名 <img src="https://tuchuang.ets2la.cn/csharp/20261018065621427.png" alt="" loading="lazy"></p><div class="tip custom-block"><p class="custom-block-title">提示</p><p>安卓（Android）手机上的2FA软件有以下几种:</p><ol><li><a href="https://github.com/beemdevelopment/Aegis" target="_blank" rel="noreferrer">Aegis Authenticator</a> 开源</li><li>Microsoft Authenticator 软件商店</li><li>Google Authenticator 软件商店</li></ol><p>苹果（iOS）</p><ol><li><a href="https://apps.apple.com/cn/app/chronos-authenticator/id6503929490" target="_blank" rel="noreferrer">Chronos Authenticator</a> 国区Apple Store</li></ol><p>鸿蒙（HarmonyOS NEXT）</p><ol><li><a href="https://appgallery.huawei.com/app/detail?id=com.example.tool_2fa&amp;channelId=SHARE&amp;source=appshare" target="_blank" rel="noreferrer">OpenAuthenticator/开源验证器</a> 应用商店</li></ol></div><div class="tip custom-block"><p class="custom-block-title">提示</p><p>根据最新的 服务隐私政策 ，未满 <strong>十四</strong> 周岁用户不要使用 <strong>账户</strong> 功能</p></div>',27)])])}const m=t(r,[["render",s]]);export{g as __pageData,m as default};
